const MUSCLE_GROUP_ORDER = ['Beine', 'Rücken', 'Brust', 'Schultern', 'Arme', 'Bauch', 'Kardio', 'Sonstige'];

// Konfiguration der Kardiogeräte: welche zusätzlichen, gerätespezifischen Werte (neben der
// Dauer in Sekunden, die weiterhin über das normale Zeit-Feld läuft) pro Satz erfasst werden
// können — inkl. Schrittweite und ggf. Maximalwert (Rudern: Widerstand bis 9). Wird sowohl im
// Übungs-Assistenten (Auswahl des Geräts) als auch beim Satz-Logging (renderActive) genutzt.
const CARDIO_MACHINES = {
  laufband: { label: 'Laufband', fields: [
    { key: 'incline', label: 'Neigung %', shortLabel: 'Neigung', unit: '%', step: 0.5, min: 0 },
    { key: 'speed', label: 'Tempo km/h', shortLabel: 'Tempo', unit: 'km/h', step: 0.1, min: 0 }
  ]},
  stepper: { label: 'Crosstrainer', fields: [
    { key: 'incline', label: 'Steigung', shortLabel: 'Steigung', unit: '', step: 1, min: 0 },
    { key: 'resistance', label: 'Widerstand', shortLabel: 'Widerstand', unit: '', step: 1, min: 0 }
  ]},
  fahrrad: { label: 'Fahrrad', fields: [
    { key: 'resistance', label: 'Widerstand', shortLabel: 'Widerstand', unit: '', step: 1, min: 0 },
    { key: 'distance', label: 'Strecke', shortLabel: 'Strecke', unit: 'm', step: 10, min: 0 }
  ]},
  rudern: { label: 'Rudern', fields: [
    { key: 'resistance', label: 'Widerstand', shortLabel: 'Widerstand', unit: '', step: 1, min: 0, max: 9 },
    { key: 'distance', label: 'Strecke', shortLabel: 'Strecke', unit: 'm', step: 10, min: 0 }
  ]},
  stairmaster: { label: 'Stairmaster', fields: [
    { key: 'speed', label: 'Geschwindigkeit', shortLabel: 'Tempo', unit: '', step: 1, min: 0 },
    { key: 'steps', label: 'Stufen', shortLabel: 'Stufen', unit: '', step: 1, min: 0 }
  ]}
};
function cardioFieldsFor(planEx){
  const cfg = planEx && planEx.cardioMachine && CARDIO_MACHINES[planEx.cardioMachine];
  return cfg ? cfg.fields : [];
}
// Distanz nur beim Laufband automatisch berechenbar (Tempo × Zeit) — bei Crosstrainer/Fahrrad/
// Rudern gibt es kein Tempo-Feld, daher keine sinnvolle Distanz herleitbar.
function cardioDistanceKm(planEx, set){
  if (!planEx || planEx.cardioMachine !== 'laufband') return null;
  if (!set || set.speed == null || set.seconds == null) return null;
  return Math.round(set.speed * (set.seconds / 3600) * 100) / 100;
}
// Kompakte Textzusammenfassung eines Kardio-Satzes (Zusatzwerte + ggf. Distanz) für
// Verlauf/PDF-Tabelle — leerer String bei Nicht-Kardio-Übungen.
function cardioSetSummary(planEx, set){
  const fields = cardioFieldsFor(planEx);
  if (!fields.length) return '';
  const parts = fields
    .map(f => set[f.key] != null ? `${f.shortLabel} ${set[f.key]}${f.unit ? ' ' + f.unit : ''}` : null)
    .filter(Boolean);
  const dist = cardioDistanceKm(planEx, set);
  if (dist != null) parts.push(`≈ ${dist.toLocaleString('de-DE')} km`);
  return parts.join(' · ');
}


